  ionViewWillLeave(){
    this.form.reset();
    this.initialValidator();
    if(this.toastinstance){
      this.toastinstance.dismiss();
    }
  }

  focusValidator(){
    const invalidControl = this.el.nativeElement.querySelector('form .ng-invalid');
    invalidControl.scrollIntoView({ behavior: "smooth", block: "center", inline: "nearest" });
    // invalidControl.scrollTo(50, 0);
    (invalidControl as HTMLElement).focus();
  }

  async presentToastWithOptions(buildId, buildName) {
    if(this.toastinstance){
      this.toastinstance.dismiss();
    }
    let text = 'B ' + buildId +' '+buildName+' opened';
      this.toastinstance = await this.toastController.create({
        header: text,
        position: 'bottom',
        cssClass: 'my-toast',
        color: 'light',
        buttons: [
          {
            text: 'Dismiss',
            role: 'cancel',
            handler: () => {
              console.log('Cancel clicked');
            }
          }
        ]
      });
    this.toastinstance.present();
  }
